<span class="line"><span style="color:#BABED8;font-style:italic;">    description</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Small Klix example app.</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span></span>
